<script>
import AppSidebar from '../components/AppSidebar.vue'
import StatsCards from '../components/StatsCards.vue'
export default { name: 'Home', components: { AppSidebar, StatsCards }, data() { return { totalCollectableThisMonth: 0, totalCollectableLastMonth: 0, numberOfDevices: 0, totalCustomers: 0, totalSalesThisMonth: 0, newCustomersThisMonth: 0, totalSalesThisYear: 0, customerAllBalance: 0, animatedCollectable: 0, animatedCollectableLastMonth: 0, animatedDevices: 0, animatedCustomers: 0, animatedSales: 0, animatedNewCustomers: 0, animatedSalesThisYear: 0, animatedCustomerBalance: 0, customers: [], barangays: [], selectedBarangay: null } }, computed: { greetingName() { const h = new Date().getHours(); return h < 12 ? 'morning' : h < 18 ? 'afternoon' : 'evening' }, primaryCards() { return [{ label: 'This month’s collectible', value: this.formatCurrency(this.animatedCollectable), icon: '₱', iconClass: 'bg-teal-50 text-teal-700', trend: 'Current cycle', trendClass: 'text-teal-700' }, { label: 'Collected this month', value: this.formatCurrency(this.animatedSales), icon: '↗', iconClass: 'bg-cyan-50 text-cyan-700', trend: 'Revenue', trendClass: 'text-cyan-700' }, { label: 'Registered members', value: this.animatedCustomers, icon: '◉', iconClass: 'bg-emerald-50 text-emerald-700', trend: `${this.animatedNewCustomers} new`, trendClass: 'text-emerald-700' }, { label: 'Connected devices', value: this.animatedDevices, icon: '⌁', iconClass: 'bg-violet-50 text-violet-700', trend: 'Monitoring', trendClass: 'text-violet-700' }] }, financialItems() { return [{ label: 'This month’s collection', value: this.formatCurrency(this.animatedSales), width: this.rate(this.animatedSales, this.animatedCollectable), barClass: 'bg-teal-600' }, { label: 'Previous month collectible', value: this.formatCurrency(this.animatedCollectableLastMonth), width: '64%', barClass: 'bg-cyan-500' }, { label: 'Year-to-date sales', value: this.formatCurrency(this.animatedSalesThisYear), width: '78%', barClass: 'bg-emerald-500' }] } }, mounted() { void this.loadDashboard(); void this.loadCustomers(); void this.loadBarangays() }, methods: { async loadDashboard() { try { const res = await fetch('/dashboard', { credentials: 'same-origin', headers: { Accept: 'application/json' } }); if (!res.ok) return; const data = await res.json(); const values = { animatedCollectable: data?.total_collectable_this_month, animatedCollectableLastMonth: data?.total_collectable_last_month, animatedDevices: data?.number_of_devices, animatedCustomers: data?.total_customers, animatedSales: data?.total_sales_this_month, animatedNewCustomers: data?.new_customers_this_month, animatedSalesThisYear: data?.total_sales_this_year, animatedCustomerBalance: data?.customer_all_balance }; Object.entries(values).forEach(([key, value]) => this.animateValue(key, Number(value || 0))) } catch (e) { console.error('Dashboard load error:', e) } }, async loadCustomers() { try { const res = await fetch('/customers', { credentials: 'same-origin', headers: { Accept: 'application/json' } }); if (res.ok) { const data = await res.json(); this.customers = Array.isArray(data?.data) ? data.data : [] } } catch (e) { console.error('Customers load error:', e) } }, async loadBarangays() { try { const res = await fetch('/barangays', { credentials: 'same-origin', headers: { Accept: 'application/json' } }); if (res.ok) { const data = await res.json(); this.barangays = Array.isArray(data?.data) ? data.data : [] } } catch (e) { console.error('Barangays load error:', e) } }, formatCurrency(value) { const n = Number(value || 0); return Number.isFinite(n) ? '₱' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '₱0.00' }, rate(part, total) { return total ? `${Math.min(100, Math.round((part / total) * 100))}%` : '0%' }, animateValue(property, target) { const start = this[property], increment = (target - start) / 20; let current = start; const timer = setInterval(() => { current += increment; if ((increment >= 0 && current >= target) || (increment < 0 && current <= target)) { this[property] = target; clearInterval(timer) } else this[property] = ['animatedDevices', 'animatedCustomers', 'animatedNewCustomers'].includes(property) ? Math.round(current) : current }, 50) }, selectBarangay(brgyId) { this.selectedBarangay = brgyId } } }
